from flask import Blueprint, request, jsonify, abort
import uuid

bp = Blueprint('{{resource}}', __name__)
store = {}

@bp.get('/{{resource}}')
def list_items():
    return jsonify(list(store.values()))

@bp.get('/{{resource}}/<{{id_field}}>')
def get_item({{id_field}}):
    item = store.get({{id_field}})
    if not item: abort(404)
    return jsonify(item)

@bp.post('/{{resource}}')
def create_item():
    data = request.get_json() or {}
    iid = str(uuid.uuid4())
    data['{{id_field}}'] = iid
    store[iid] = data
    return jsonify(data), 201

@bp.put('/{{resource}}/<{{id_field}}>')
def update_item({{id_field}}):
    if {{id_field}} not in store: abort(404)
    store[{{id_field}}].update(request.get_json() or {})
    return jsonify(store[{{id_field}}])

@bp.delete('/{{resource}}/<{{id_field}}>')
def delete_item({{id_field}}):
    store.pop({{id_field}}, None)
    return '', 204
